local SettingRefBase = require('Game.Setting.SettingRefBase')
local base = SettingRefBase
local ParseUtils = CS.ParseUtils
local ChapterUtils = import('Game.Chapter.ChapterUtils')

---@class NewChapterMessageVo
local NewChapterMessageVo = Class("NewChapterMessageVo", SettingRefBase)

---__int
function NewChapterMessageVo:__init()
    self.messageId = nil              --消息组id
    self.head2Text = nil              --对话人
    self.text = nil              --对话内容
    self.head1Text = nil              --群组名称
    self.head1 = nil              --群组头像
    self.head2 = nil              --对话头像
    self.isShowHint = nil        -- 是否显示点击提示
    self.isIcon = nil            -- 是否是图片
    self.feText = nil              --对话 女
    self.feHead2 = nil             --头像 女
    self.waitTime = nil
    self.isMe = nil              --左边1,右边2
end

---FillVo
---@param row TableML.TableFileRow
function NewChapterMessageVo:FillVo(row)
    base.FillVo(self,row)
    self.messageId = parse_number(row, "messageId")
    self.head2Text = parse_localizeText(row, "head2Text")
    self.text = parse_localizeText(row, "text")
    self.head1Text = parse_localizeText(row, "head1Text")
    self.head1 = ParseUtils.ParsePathName(row, "head1")
    self.head2 = ParseUtils.ParsePathName(row, "head2")
    self.isIcon = parse_number(row,"isIcon") == 1
    self.emoPath = ParseUtils.ParsePathName(row, "emoPath")
    self.isShowHint =  parse_number(row, "isShowHint",0) == 1        -- 是否显示点击提示
    self.feText = ParseUtils.ParseChapterLocalizeText(row, "feText",self.text)
    self.feHead2 = ParseUtils.ParsePathName(row, "feHead2")
    self.waitTime = parse_number(row,"waitTime",1)
    self.isMe = parse_number(row, "isMe",1) == 1
end

---获取对话内容
function NewChapterMessageVo:GetDialogContent()
    local str = self.text
    if CfUtils.IsWoman() then
        if not string.isEmpty(self.feText) then
            str = self.feText
        end
    end
    str = string.gsub(str,"\\n", "\n")
    return str
end
---获取头像  要分男女
function NewChapterMessageVo:GetHeadIcon()
    if CfUtils.IsWoman() then
        if not isNull(self.feHead2) then
            return self.feHead2
        end
    end
    return self.head2
end

function NewChapterMessageVo:GetEmoIcon()
    return self.emoPath
end

function NewChapterMessageVo:GetHeadText()
    local text = ChapterUtils.ReplaceStr(self.head2Text, "#playerName",self:GetPlayerName())
    return text
end

function NewChapterMessageVo:GetPlayerName()
    local playerComp = ChapterUtils.GetPlayerComp()
    if playerComp and playerComp.playerDojo then
        return playerComp.playerDojo.playerName
    end
    return ""
end

function NewChapterMessageVo:__delete()
    self.messageId = nil
    self.head2Text = nil
    self.text = nil
    self.head1Text = nil
    self.head1 = nil
    self.head2 = nil
    self.isMe = nil
    self.isShowHint = nil        -- 是否显示点击提示
    self.feText = nil
    self.waitTime = nil
    self.feHead2 = nil
end

return NewChapterMessageVo
